@props([
    /** Tech name (case-insensitive). e.g. "PHP", "Laravel", "JS", "Tailwind". */
    'tech' => '',
    /** Render variant: 'chip' (small inline), 'card' (large grid cell), 'icon' (just the SVG). */
    'variant' => 'chip',
])

@php
    // Normalize the input so common aliases (JS / JavaScript, TW / Tailwind, etc.) all match.
    $key = strtolower(trim($tech));
    $key = match (true) {
        in_array($key, ['php']) => 'php',
        in_array($key, ['laravel', 'l']) => 'laravel',
        in_array($key, ['livewire', 'lw']) => 'livewire',
        in_array($key, ['alpine', 'alpine.js', 'alpinejs']) => 'alpine',
        in_array($key, ['tailwind', 'tailwindcss', 'tailwind css', 'tw']) => 'tailwind',
        in_array($key, ['js', 'javascript']) => 'javascript',
        in_array($key, ['ts', 'typescript']) => 'typescript',
        in_array($key, ['vue', 'vue.js', 'vuejs']) => 'vue',
        in_array($key, ['react', 'react.js']) => 'react',
        in_array($key, ['node', 'node.js', 'nodejs']) => 'node',
        in_array($key, ['mysql', 'db']) => 'mysql',
        in_array($key, ['postgres', 'postgresql', 'pg']) => 'postgres',
        in_array($key, ['vite']) => 'vite',
        in_array($key, ['git']) => 'git',
        in_array($key, ['docker']) => 'docker',
        in_array($key, ['html', 'html5']) => 'html',
        in_array($key, ['css', 'css3']) => 'css',
        default => null,
    };

    // Brand-color + SimpleIcons paths. Keep them inline so no external dependency.
