@if ($iconData && $variant === 'card')
    <div class="text-center fade-in" {{ $attributes }}>
        <div class="card-dark rounded-lg p-6 mb-3 flex items-center justify-center
                    h-24 transition-all duration-200" style="color: {{ $iconData['color'] }}">
            <svg class="w-12 h-12" fill="currentColor" viewBox="0 0 24 24" aria-hidden="true">
                <path d="{{ $iconData['path'] }}"/>
            </svg>
        </div>
        <p class="text-sm text-white">{{ $iconData['label'] }}</p>
    </div>
@elseif ($iconData && $variant === 'chip')
    <span class="inline-flex items-center gap-1.5 bg-dark-primary text-dark-accent text-xs px-2.5 py-1 rounded"
          {{ $attributes }}>
        <svg class="w-3.5 h-3.5 flex-shrink-0" fill="currentColor" viewBox="0 0 24 24"
             style="color: {{ $iconData['color'] }}" aria-hidden="true">
            <path d="{{ $iconData['path'] }}"/>
        </svg>
        {{ $iconData['label'] }}
    </span>
@elseif ($iconData)
    {{-- variant === 'icon' --}}
    <svg class="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"
         style="color: {{ $iconData['color'] }}" aria-label="{{ $iconData['label'] }}" role="img"
         {{ $attributes }}>
        <path d="{{ $iconData['path'] }}"/>
    </svg>
@else
    {{-- Unknown tech: fall back to text chip --}}
    <span class="inline-block bg-dark-primary text-dark-muted text-xs px-2 py-1 rounded" {{ $attributes }}>
        {{ $tech }}
    </span>
@endif
